import{_ as t,a,b as r,c as o,d as s}from"./chunks/grip_measurement_manual.C2wiyj0l.js";import{_ as n,o as i,c as l,a0 as h}from"./chunks/framework.akKRIpjQ.js";const y=JSON.parse('{"title":"02 · Grip Size Measurement","description":"","frontmatter":{},"headers":[],"relativePath":"guide/02-grip-size-measurement.md","filePath":"guide/02-grip-size-measurement.md"}'),d={name:"guide/02-grip-size-measurement.md"};function u(p,e,g,m,c,f){return i(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="_02-·-grip-size-measurement" tabindex="-1">02 · Grip Size Measurement <a class="header-anchor" href="#_02-·-grip-size-measurement" aria-label="Permalink to &quot;02 · Grip Size Measurement&quot;">​</a></h1><blockquote><p>Feature 1 of 4. <strong>Two entry points</strong> lead to the same three-system size output (Yonex L0–L5 / Wilson in fractions / Head–Prince–Babolat equivalent):</p><ul><li>🤖 <strong>AI measurement</strong> — snap a palm photo, on-device MediaPipe Hand computes palm length + width + finger count</li><li>📏 <strong>Manual measurement</strong> — measure with a ruler, type the number in, <strong>goes through the exact same size formula</strong></li></ul><p>Both paths share the same sizing formula, so use whichever is more accurate; cross-validate with both if you like.</p></blockquote><hr><h2 id="two-paths-at-a-glance" tabindex="-1">Two paths at a glance <a class="header-anchor" href="#two-paths-at-a-glance" aria-label="Permalink to &quot;Two paths at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>🤖 AI measurement (photo)</th><th>📏 Manual measurement (ruler)</th></tr></thead><tbody><tr><td><strong>Entry</strong></td><td>Home → &quot;AI Grip Size&quot; → Start</td><td>Home → same card → &quot;Manual Tier Picker&quot;</td></tr><tr><td><strong>Requires</strong></td><td>Rear camera + on-device ML model</td><td>Any ruler</td></tr><tr><td><strong>Time</strong></td><td>30 sec (shoot + adjust + result)</td><td>10 sec (measure + type)</td></tr><tr><td><strong>Accuracy</strong></td><td>RMSE ±4.2 mm ≈ ±⅓ tier</td><td>Depends on ruler precision</td></tr><tr><td><strong>When to use</strong></td><td>No ruler / quick first read / want palm + wrist texture</td><td>No camera / camera denied / AI keeps failing / want precise control over start point</td></tr></tbody></table><p>Covered in detail below. <strong>AI is the default</strong> for most users; <strong>manual is the fallback</strong> + a great ground-truth check for AI.</p><hr><h1 id="🤖-ai-measurement-photo" tabindex="-1">🤖 AI measurement (photo) <a class="header-anchor" href="#🤖-ai-measurement-photo" aria-label="Permalink to &quot;🤖 AI measurement (photo)&quot;">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><img src="'+t+`" alt="Aiming the camera at the palm" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Hold the phone up to your palm. The App estimates the following <strong>on-device by default (no upload)</strong>:</p><ul><li><strong>Palm length</strong> (mm)</li><li><strong>Palm width</strong> (mm)</li><li><strong>Finger count + ratios</strong> (calibration across hand shapes)</li><li>→ Recommended grip size in three systems simultaneously</li></ul><h2 id="how-to-shoot-accurately" tabindex="-1">How to shoot accurately <a class="header-anchor" href="#how-to-shoot-accurately" aria-label="Permalink to &quot;How to shoot accurately&quot;">​</a></h2><h3 id="key-1-place-on-a-flat-desk-lay-an-a4-sheet-palm-up-flat-with-fingers-spread" tabindex="-1">Key 1: place on a flat desk, lay an A4 sheet, palm-up flat with fingers spread <a class="header-anchor" href="#key-1-place-on-a-flat-desk-lay-an-a4-sheet-palm-up-flat-with-fingers-spread" aria-label="Permalink to &quot;Key 1: place on a flat desk, lay an A4 sheet, palm-up flat with fingers spread&quot;">​</a></h3><p>&lt;img src=&quot;/images/grip_measurement_1.jpg&quot; alt=&quot;Before the shot: palm flat on A4 paper, green frame in place — &quot;Place an A4 paper flat on the desk&quot;&quot; style=&quot;max-width: 320px; border-radius: 12px; margin: 12px 0;&quot; /&gt;</p><blockquote><p>This is the <strong>live preview</strong> before shooting: the screen when the phone is directly overhead — preview + pre-computed green frame at 30 cm working distance + bottom hint &quot;Place an A4 paper flat on the desk&quot;. Get the A4 fully inside the green frame, palm up with fingers spread, then tap the shutter.</p></blockquote><ul><li><strong>Desk must be flat</strong> — a hard flat surface with a white A4 sheet. Don&#39;t hold the palm in mid-air, don&#39;t rest on a soft surface.</li><li><strong>Palm flat on the paper, fingers spread</strong> — skin-on-paper gives the AI a clear edge to anchor on; the A4 dimensions also back out the camera distance (close to 30 cm).</li><li><strong>Palm facing the camera</strong> — the back-of-hand has too little texture, AI will struggle to localize; the palm-side that&#39;s on the paper has the richest texture.</li><li><strong>Fingers straight</strong> — natural straight + spread, even if you have to push a bit; never curled.</li></ul><h3 id="key-2-even-lighting" tabindex="-1">Key 2: even lighting <a class="header-anchor" href="#key-2-even-lighting" aria-label="Permalink to &quot;Key 2: even lighting&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ✅ Good              ❌ Bad</span></span>
<span class="line"><span>┌────────────┐     ┌────────────┐</span></span>
<span class="line"><span>│  by wall   │     │ cluttered  │</span></span>
<span class="line"><span>│   🖐       │     │   🖐 + 📦   │</span></span>
<span class="line"><span>│            │     │            │</span></span>
<span class="line"><span>└────────────┘     └────────────┘</span></span></code></pre></div><ul><li>Light should be even; angled window light is better than overhead (less harsh shadows).</li><li>Turn off flash if there&#39;s enough light.</li><li>White A4 paper also &quot;diffuses&quot; overhead hard light — yet another reason to lay it down.</li></ul><h3 id="key-3-shoot-straight-down" tabindex="-1">Key 3: shoot straight down <a class="header-anchor" href="#key-3-shoot-straight-down" aria-label="Permalink to &quot;Key 3: shoot straight down&quot;">​</a></h3><ul><li>Not at an angle — straight overhead.</li><li>Camera ≈ 30–50 cm above the paper.</li><li>Use the <strong>rear</strong> camera (front has heavy distortion).</li></ul><h2 id="capture-flow" tabindex="-1">Capture flow <a class="header-anchor" href="#capture-flow" aria-label="Permalink to &quot;Capture flow&quot;">​</a></h2><ol><li>Home → &quot;AI Grip Size&quot;</li><li>&quot;Start&quot; → camera permission prompt (first time)</li><li>Shoot straight down (≈ 30–50 cm), frame on the flat palm, hold still for 1 sec while pose pre-check runs</li><li>Shutter (or auto-trigger)</li><li>Wait 1–2 sec: on-device MediaPipe Hand runs → result page</li></ol><h2 id="result-page" tabindex="-1">Result page <a class="header-anchor" href="#result-page" aria-label="Permalink to &quot;Result page&quot;">​</a></h2><img src="`+a+'" alt="Measurement result" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>The result page shows the recognition result overlaid on your photo:</p><table tabindex="0"><thead><tr><th>Panel</th><th>Content</th></tr></thead><tbody><tr><td><strong>Photo + overlay</strong></td><td>Your palm + AI-drawn <strong>transverse line</strong> (the boundary between palm and wrist)</td></tr><tr><td><strong>Measurements</strong></td><td>Palm length + palm width (mm)</td></tr><tr><td><strong>Recommendations</strong></td><td>Yonex / Wilson / Head–Prince–Babolat simultaneously</td></tr></tbody></table><img src="'+r+`" alt="Measurement result — three-system grid" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Three-system grid example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             Yonex   Wilson    Head / Prince / Babolat</span></span>
<span class="line"><span>             L3      4½&quot;       4¾</span></span></code></pre></div><h2 id="two-correction-paths-for-the-ai-result" tabindex="-1">Two correction paths for the AI result <a class="header-anchor" href="#two-correction-paths-for-the-ai-result" aria-label="Permalink to &quot;Two correction paths for the AI result&quot;">​</a></h2><p>Before we dive into the result page details, here are the <strong>two correction modes</strong> the App provides — pick whichever fits the situation.</p><h3 id="mode-1-—-drag-the-transverse-line-on-the-result-page-preferred" tabindex="-1">Mode 1 — drag the transverse line on the result page (preferred) <a class="header-anchor" href="#mode-1-—-drag-the-transverse-line-on-the-result-page-preferred" aria-label="Permalink to &quot;Mode 1 — drag the transverse line on the result page (preferred)&quot;">​</a></h3><p>This mode lets you <strong>drag the transverse line</strong> on the photo. The line is the AI&#39;s &quot;palm start position&quot; — if it&#39;s 5 mm too high (toward the fingertips), the recommended size jumps one tier.</p><ul><li>After the shot, you&#39;ll see an AI-drawn <strong>wrist transverse line</strong> on the photo</li><li><strong>Long-press, then drag up/down</strong> to move it</li><li>The &quot;Measurements&quot; + &quot;Recommendations&quot; panels update <strong>in real time</strong></li><li>Drag range is clamped to ±15 mm from the AI&#39;s initial position (to avoid absurd values)</li><li>Tap &quot;Save to history&quot; when satisfied</li></ul><blockquote><p>Use this mode when &quot;AI number is roughly right, just a bit off (typically 3–10 mm)&quot;.</p></blockquote><h3 id="mode-2-—-adjust-green-frame-page-fit-the-a4-sheet-to-the-green-frame" tabindex="-1">Mode 2 — Adjust Green Frame page: fit the A4 sheet to the green frame <a class="header-anchor" href="#mode-2-—-adjust-green-frame-page-fit-the-a4-sheet-to-the-green-frame" aria-label="Permalink to &quot;Mode 2 — Adjust Green Frame page: fit the A4 sheet to the green frame&quot;">​</a></h3><p>If the <strong>overall scale</strong> is wrong — e.g., you wore multiple overgrips and the image looks elongated/compressed — switch to the <strong>Adjust page</strong> to give the App a known physical reference.</p><p>The page title is <strong>&quot;Adjust Green Frame&quot;</strong>, showing:</p><img src="`+o+'" alt="Adjust page — fit A4 paper edges to the green rectangle" style="max-width:320px;border-radius:12px;margin:12px 0;"><ul><li>The full shot (palm + A4)</li><li>A <strong>cyan-green rectangle</strong> the App computed for a 30 cm standard working distance</li><li>A bottom hint: <strong>&quot;Drag with one finger; pinch to zoom (rotation disabled). Fit the A4 inside the green frame, then Next.&quot;</strong></li><li>A green <strong>Next (Analyze)</strong> button</li></ul><p>How to operate:</p><ul><li><strong>One finger drag</strong> — pan the photo so the A4 sheet is centered in the green frame</li><li><strong>Two-finger pinch / spread</strong> — zoom the photo so <strong>all four edges of the A4 sheet hug the green frame</strong></li><li>Stop when the four paper edges <strong>overlap the green frame</strong> — the tighter, the more accurate</li><li><strong>Rotation is disabled</strong> (so you don&#39;t accidentally rotate the photo)</li><li>When satisfied, tap <strong>Next (Analyze)</strong> — the App re-runs palm-length detection at the corrected scale</li></ul><blockquote><p>An A4 sheet is 210 × 297 mm; telling the App &quot;this green frame = an A4 at this working distance&quot; nails down <strong>absolute scale</strong> — something Mode 1 alone can&#39;t do.</p><p>Combine the two modes: <strong>Mode 2 fixes scale, Mode 1 fixes palm start</strong>.</p></blockquote><h2 id="error-budget-and-mitigations" tabindex="-1">Error budget and mitigations <a class="header-anchor" href="#error-budget-and-mitigations" aria-label="Permalink to &quot;Error budget and mitigations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td><strong>Palm tilted</strong></td><td>Length ±5–8 mm</td><td>App says &quot;place flat&quot;</td></tr><tr><td><strong>Focal distortion</strong> (front cam)</td><td>Length ±3 mm</td><td>Default forces rear cam</td></tr><tr><td><strong>Skin tone / lighting</strong></td><td>Keypoint shift ±2 mm</td><td>MediaPipe Hand 2024 model is robust across tones</td></tr><tr><td><strong>Partial occlusion</strong> (ring, long nails)</td><td>Failure / oversized</td><td>Remove rings, trim nails first</td></tr><tr><td><strong>Hand-shape training bias</strong></td><td>±3 mm</td><td>Use Mode 1 (drag line) or Mode 2 (adjust page)</td></tr></tbody></table><blockquote><p><strong>Measured RMSE</strong>: 4.2 mm on-device. In tier terms: about <strong>±⅓ tier</strong> in the Yonex system.</p></blockquote><h2 id="limits-and-edges" tabindex="-1">Limits and edges <a class="header-anchor" href="#limits-and-edges" aria-label="Permalink to &quot;Limits and edges&quot;">​</a></h2><ul><li>❌ <strong>Gloves not supported</strong> — gloves drop keypoints</li><li>❌ <strong>Children&#39;s hands</strong> — training set is mostly adults; kids won&#39;t be accurate</li><li>❌ <strong>Extreme lighting</strong> (very dark, strong backlight) — shot fails → use Adjust page, or 📏 manual measurement</li><li>❌ <strong>Multiple hands in frame</strong> — App auto-picks the largest (often wrong)</li></ul><h2 id="no-original-photo-saved" tabindex="-1">No original photo saved <a class="header-anchor" href="#no-original-photo-saved" aria-label="Permalink to &quot;No original photo saved&quot;">​</a></h2><p>V1.1 <strong>does not save</strong> the original photo. After measurement, only the <strong>keypoint coordinate array</strong> (~80 bytes) is cached for history replay; the <strong>photo is discarded immediately</strong>. If you need to keep a copy, go to Settings → Data management → Enable original photo archive (off by default).</p><hr><h1 id="📏-manual-measurement-ruler" tabindex="-1">📏 Manual measurement (ruler) <a class="header-anchor" href="#📏-manual-measurement-ruler" aria-label="Permalink to &quot;📏 Manual measurement (ruler)&quot;">​</a></h1><blockquote><p><strong>This path uses the exact same size formula as the AI path</strong> — only the entry differs. So if your ruler reading is accurate, the result will match what AI computes; if AI was off, manual measurement is a great ground-truth check.</p></blockquote><img src="'+s+'" alt="Manual picker — ruler method, palm length input, size result" style="max-width:320px;border-radius:12px;margin:12px 0;"><h2 id="entry" tabindex="-1">Entry <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Entry&quot;">​</a></h2><p>Home → &quot;AI Grip Size&quot; card → &quot;<strong>Manual Tier Picker</strong>&quot; link below.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Pick your dominant hand</strong> (left / right) — the diagram on the page flips accordingly</li><li><strong>Measure with a ruler</strong>: from directly below the <strong>ring fingertip</strong> down to the <strong>transverse line</strong> (the second crease counting up from the wrist crease — the palm / finger boundary)</li><li>That distance is your <strong>rulerMm</strong> — the &quot;palm length&quot; used in the sizing formula</li><li>Type it into the <strong>Ruler Method Measurement</strong> input (mm); you can leave it blank and pick a tier directly</li><li>Optional: fill in <strong>Palm Length (mm, optional)</strong> if you measured from the wrist crease to the ring fingertip instead of the transverse line to the ring fingertip</li><li>The App applies the <strong>exact same formula as AI camera mode</strong> and outputs <strong>Yonex / Wilson / Head–Prince–Babolat</strong></li></ol><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><ul><li>Camera permission denied / no camera</li><li>Repeated AI failure (extreme lighting, gloves, very small hands)</li><li>You already have a ruler reading and just want to type it in</li><li>You want a sanity check against the AI result</li></ul><h2 id="how-to-measure-well" tabindex="-1">How to measure well <a class="header-anchor" href="#how-to-measure-well" aria-label="Permalink to &quot;How to measure well&quot;">​</a></h2><ul><li>A <strong>soft tape measure</strong> or <strong>rigid ruler + caliper</strong> both work; mm precision is enough (output is ⅛&quot; tiers)</li><li><strong>Ring finger</strong> is the standard sizing finger (index and middle are longer, which cross-system comparisons won&#39;t agree on)</li><li><strong>Transverse line</strong>: the boundary between palm and fingers. Curl your hand, then release — you&#39;ll see 3 creases: wrist, palm-mid, finger-base. <strong>Take the middle one</strong></li><li>Measure with the <strong>hand naturally relaxed</strong> — don&#39;t force it open (that adds 1–3 mm)</li></ul><hr><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad? <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to &quot;iPhone / iPad?&quot;">​</a></h3><p>Not supported in this version. See <a href="./00-introduction.html#supported-platforms">00 · Supported platforms</a>.</p><h3 id="how-powerful-does-the-device-need-to-be-for-on-device-detection" tabindex="-1">How powerful does the device need to be for on-device detection? <a class="header-anchor" href="#how-powerful-does-the-device-need-to-be-for-on-device-detection" aria-label="Permalink to &quot;How powerful does the device need to be for on-device detection?&quot;">​</a></h3><p>Snapdragon 7xx / Dimensity 800 or higher recommended. Low-end devices may feel &quot;spinning&quot; for a few seconds.</p><h3 id="does-the-data-get-uploaded" tabindex="-1">Does the data get uploaded? <a class="header-anchor" href="#does-the-data-get-uploaded" aria-label="Permalink to &quot;Does the data get uploaded?&quot;">​</a></h3><p><strong>No</strong>. All computation runs on-device; the photo never leaves your phone.</p><h3 id="will-ai-and-manual-produce-the-same-size" tabindex="-1">Will AI and manual produce the same size? <a class="header-anchor" href="#will-ai-and-manual-produce-the-same-size" aria-label="Permalink to &quot;Will AI and manual produce the same size?&quot;">​</a></h3><p><strong>In theory, yes</strong> — both paths share the same formula; in practice, expect ~⅓ tier difference (sources: AI measurement error ±4.2 mm + ruler reading error). If the two paths differ by ≥ 1 tier, run each <strong>twice</strong> and take the median, or treat 📏 manual&#39;s rulerMm as ground truth.</p><h3 id="i-don-t-agree-with-the-ai-result-—-what-are-my-options" tabindex="-1">I don&#39;t agree with the AI result — what are my options? <a class="header-anchor" href="#i-don-t-agree-with-the-ai-result-—-what-are-my-options" aria-label="Permalink to &quot;I don&#39;t agree with the AI result — what are my options?&quot;">​</a></h3><p>From highest precision to lowest:</p><ol><li><strong>Drag the transverse line on the result page</strong> — long-press its handle and drag; the measurement + recommendation panels update in real time. <strong>Use this when AI is roughly right but a bit off (typically 3–10 mm).</strong></li><li><strong>Adjust page</strong> — on the result page tap &quot;Adjust scale only&quot; → a ±10 mm slider. <strong>Use this when you&#39;ve already measured with a ruler and just want to type the number in</strong>, or when on-device detection fails entirely and you can&#39;t see the photo.</li><li><strong>Skip AI entirely → 📏 Manual measurement</strong> — the fallback path; completely independent of AI.</li></ol>',77)])])}const q=n(d,[["render",u]]);export{y as __pageData,q as default};
